            // Cola offline: solo en errores de red (timeout, abort, o sin conexión)
            // Usamos e.name en lugar de instanceof para compatibilidad cross-realm (vm tests)
            const isNetworkError = e.name === 'AbortError' || e.name === 'TimeoutError'
